import boto3

def get_cognito_client(config=None):
    config = config or {}
    return boto3.client('cognito-idp', region_name=config.get('region'))

from dataclasses import dataclass


@dataclass
class LoginRequest:
    ClientId: str
    Username: str
    Password: str

    @staticmethod
    def to_dict(self):
        return {'ClientId': self.ClientId, 'Username': self.Username, 'Password': self.Password}


@dataclass
class LoginResponse:
    AuthenticationResult: dict

    @staticmethod
    def from_dict(data):
        return LoginResponse(AuthenticationResult=data['AuthenticationResult'])

    def to_dict(self):
        return {'AuthenticationResult': self.AuthenticationResult}


@dataclass
class RefreshRequest:
    ClientId: str
    RefreshToken: str

    @staticmethod
    def to_dict(self):
        return {'ClientId': self.ClientId, 'RefreshToken': self.RefreshToken}


@dataclass
class RefreshResponse:
    AuthenticationResult: dict

    @staticmethod
    def from_dict(data):
        return RefreshResponse(AuthenticationResult=data['AuthenticationResult'])

    def to_dict(self):
        return {'AuthenticationResult': self.AuthenticationResult}

import re


def profile_moderation(text):
    if re.search(r'\b(badword1|badword2)\b', text, re.IGNORECASE):
        return {'status': 'rejected', 'reason': 'Contains inappropriate content'}
    return {'status': 'approved'}

from google.cloud import firestore


def profile_note_store(user_id, note):
    db = firestore.Client()
    doc_ref = db.collection('onboarding_notes').document(user_id)
    doc_ref.set({'note': note})
    return {'status': 'success'}
